import unittest

from health import HealthClient
from settings import Settings


class FakeTransport:
    def __init__(self):
        self.timeout = None

    def request(self, path, *, timeout=None):
        self.timeout = timeout
        return {"status": "ok"}


class HealthClientTest(unittest.TestCase):
    def test_configured_timeout_is_used(self):
        transport = FakeTransport()
        result = HealthClient(transport, Settings(request_timeout=2.5)).check()
        self.assertEqual({"status": "ok"}, result)
        self.assertEqual(2.5, transport.timeout)


if __name__ == "__main__":
    unittest.main()
